<div id="dts-video-modal" style="display:none;position:fixed;inset:0;background:rgba(10,10,10,0.94);z-index:9999;align-items:center;justify-content:center;padding:40px;">
  <button type="button" id="dts-video-modal-close" style="position:absolute;top:28px;right:36px;width:44px;height:44px;border-radius:50%;background:rgba(255,255,255,0.1);border:1px solid rgba(255,255,255,0.2);color:#fff;font-size:20px;cursor:pointer;display:flex;align-items:center;justify-content:center;">×</button>
  <video id="dts-video-modal-player" controls playsinline style="max-width:1000px;width:100%;max-height:80vh;border-radius:var(--r-lg);background:#000;">
    <source src="https://www.datastore.com.br/novosite2026/datastore1tri.mp4" type="video/mp4">
  </video>
