<script>
document.addEventListener('DOMContentLoaded', function(){
  var openBtn = document.getElementById('dts-video-play-btn');
  var openBtnMobile = document.getElementById('dts-video-play-btn-mobile');
  var closeBtn = document.getElementById('dts-video-modal-close');
  var modal = document.getElementById('dts-video-modal');
  var player = document.getElementById('dts-video-modal-player');
  if(!modal || !player) return;
  function openVideoModal(){
    modal.style.display = 'flex';
    player.currentTime = 0;
    player.muted = false;
    player.play();
    document.body.style.overflow = 'hidden';
  }
  if (openBtn) openBtn.addEventListener('click', openVideoModal);
  if (openBtnMobile) openBtnMobile.addEventListener('click', openVideoModal);
  function closeModal(){
    modal.style.display = 'none';
    player.pause();
    document.body.style.overflow = '';
  }
  closeBtn.addEventListener('click', closeModal);
  modal.addEventListener('click', function(e){
    if(e.target === modal) closeModal();
  });
});
</script>

